// Generated by datasets/weda-fall/train_weda.py. Magnitudes only.

export const WEDA_WINDOW = 30;
export const WEDA_LOW_G = 0.6;
export const WEDA_HIGH_G = 2.2;
export const WEDA_THRESHOLD = 0.72;
export const WEDA_BIAS = -0.26679290;
export const WEDA_MEAN = [0.66154231, 2.19551399, 0.33062293, 314.03124187, 0.02810474, 0.03187769, 0.16413603, 1.53397168] as const;
export const WEDA_STD = [0.21351179, 1.29910162, 0.32839334, 222.30146737, 0.06240502, 0.06581927, 0.37039896, 1.43271751] as const;
export const WEDA_WEIGHT = [-0.16900380, 0.44127269, -0.01137763, 0.19875954, -0.23688933, -0.34276397, 0.10482967, 0.42530531] as const;

export type WristSample = {
  ax: number;
  ay: number;
  az: number;
  gx: number;
  gy: number;
  gz: number;
};

function sigmoid(value: number): number {
  const clipped = Math.max(-30, Math.min(30, value));
  return 1 / (1 + Math.exp(-clipped));
}

/** Fall score for one 3-second wrist window. Null until 30 samples exist. */
export function wedaFallScore(samples: readonly WristSample[]): number | null {
  if (samples.length < WEDA_WINDOW) return null;
  const window = samples.slice(samples.length - WEDA_WINDOW);
  const accel: number[] = [];
  const gyro: number[] = [];
  for (const sample of window) {
    accel.push(Math.hypot(sample.ax, sample.ay, sample.az));
    gyro.push(Math.hypot(sample.gx, sample.gy, sample.gz));
  }
  const avg = accel.reduce((sum, value) => sum + value, 0) / accel.length;
  const spread = Math.sqrt(accel.reduce((sum, value) => sum + (value - avg) ** 2, 0) / accel.length);
  const amin = Math.min(...accel);
  const amax = Math.max(...accel);
  let dip = -1;
  let impact = -1;
  for (let i = 0; i < accel.length; i++) {
    if (dip < 0 && accel[i] < WEDA_LOW_G) dip = i;
    if (accel[i] > WEDA_HIGH_G) impact = i;
  }
  const features = [
    amin,
    amax,
    spread,
    Math.max(...gyro),
    accel.filter((value) => value < WEDA_LOW_G).length / accel.length,
    accel.filter((value) => value > WEDA_HIGH_G).length / accel.length,
    dip >= 0 && impact > dip ? 1 : 0,
    amax - amin,
  ];
  let score = WEDA_BIAS;
  for (let i = 0; i < features.length; i++) {
    score += WEDA_WEIGHT[i] * ((features[i] - WEDA_MEAN[i]) / WEDA_STD[i]);
  }
  return sigmoid(score);
}
